sp_portal.css_variables:
/* ── Animations ── */
@keyframes shimmerSweep {
  0%   { background-position: -300% center; }
  100% { background-position: 300% center; }
}
@keyframes breatheGlow {
  0%, 100% { box-shadow: 0 0 6px rgba(20,184,166,0.35), 0 0 16px rgba(20,184,166,0.12); }
  50%       { box-shadow: 0 0 20px rgba(20,184,166,0.75), 0 0 44px rgba(20,184,166,0.28); }
}
@keyframes badgeBreathe {
  0%,100% { transform: scale(1); }
  50%     { transform: scale(1.08); }
}
@keyframes taglineReveal {
  from { opacity: 0; letter-spacing: 6px; }
  to   { opacity: 1; letter-spacing: 3px; }
}
@keyframes pulseWave {
  0%   { background-position: 0% 0%; }
  100% { background-position: 200% 0%; }
}

.navbar-brand,
.sp-nav .navbar-brand {
  position: relative !important;
  display: inline-flex !important;
  align-items: center !important;
  gap: 0 !important;
  padding: 7px 18px 7px 14px !important;
  border-radius: 12px !important;
  border: 1px solid rgba(20, 184, 166, 0.35) !important;
  background: linear-gradient(135deg,
    rgba(10, 50, 60, 0.6) 0%,
    rgba(0, 70, 80, 0.4) 100%
  ) !important;
  backdrop-filter: blur(8px) !important;
  animation: breatheGlow 3s ease-in-out infinite !important;
  text-decoration: none !important;
  transition: all 0.3s ease !important;
  border-bottom: 2px solid transparent !important;
  background-clip: padding-box !important;
}

/* ── Glowing pulse-wave line at the bottom ── */
.navbar-brand::after,
.sp-nav .navbar-brand::after {
  content: '' !important;
  position: absolute !important;
  bottom: -2px !important;
  left: 0 !important;
  width: 100% !important;
  height: 2px !important;
  background: linear-gradient(
    90deg,
    transparent 0%,
    #f4a261     20%,
    #f4a261     28%,
    transparent 34%,
    #2dd4bf     55%,
    #5eead4     70%,
    transparent 100%
  ) !important;
  background-size: 200% 100% !important;
  animation: pulseWave 3s linear infinite !important;
  border-radius: 2px !important;
}

/* ── MDC badge before the text ── */
.navbar-brand::before,
.sp-nav .navbar-brand::before {
  content: 'MDC' !important;
  font-family: 'Segoe UI', 'Trebuchet MS', sans-serif !important;
  font-size: 13px !important;
  font-weight: 900 !important;
  letter-spacing: 1px !important;
  padding: 3px 8px !important;
  border-radius: 6px !important;
  margin-right: 10px !important;
  background: linear-gradient(135deg, #f4a261 0%, #e76f51 100%) !important;
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  box-shadow: 0 2px 8px rgba(244, 162, 97, 0.5) !important;
  flex-shrink: 0 !important;
  animation: badgeBreathe 2.4s ease-in-out infinite !important;
}

.navbar-brand,
.navbar-brand span,
.sp-nav .navbar-brand {
  font-family: 'Segoe UI', 'Trebuchet MS', sans-serif !important;
  font-size: 16px !important;
  font-weight: 900 !important;
  letter-spacing: 1.5px !important;
  text-transform: uppercase !important;
  background: linear-gradient(
    90deg,
    #ffffff  0%,
    #ccfbf1 20%,
    #2dd4bf 35%,
    #ffffff 50%,
    #5eead4 65%,
    #2dd4bf 80%,
    #ffffff 100%
  ) !important;
  background-size: 300% auto !important;
  -webkit-background-clip: text !important;
  -webkit-text-fill-color: transparent !important;
  background-clip: text !important;
  animation: shimmerSweep 4s linear infinite, breatheGlow 3s ease-in-out infinite !important;
  text-shadow: none !important;
  text-decoration: none !important;
}

/* ── Hover ── */
.navbar-brand:hover,
.sp-nav .navbar-brand:hover {
  border-color: rgba(20, 184, 166, 0.7) !important;
  background: linear-gradient(135deg,
    rgba(10, 50, 60, 0.8) 0%,
    rgba(0, 90, 100, 0.6) 100%
  ) !important;
  animation: shimmerSweep 1.5s linear infinite, breatheGlow 1s ease-in-out infinite !important;
  text-decoration: none !important;
  transform: translateY(-1px) !important;
}

/* ── Responsive ── */
@media (max-width: 768px) {
  .navbar-brand,
  .navbar-brand span,
  .sp-nav .navbar-brand {
    font-size: 12px !important;
    letter-spacing: 0.8px !important;
    padding: 5px 10px 5px 8px !important;
  }
  .navbar-brand::before,
  .sp-nav .navbar-brand::before {
    font-size: 10px !important;
    padding: 2px 6px !important;
    margin-right: 7px !important;
  }
}
